import type { DialogueEntry } from '../../../types';
import { CharacterId } from '../characters';
import { Portrait } from '../portraits';
import { Background } from '../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "雨從黃昏開始下，到了亥時還沒有要停的意思。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "山上的雨不是落下來的，是橫著掃過來的，一陣一陣拍在竹簾上，像有人在外面不耐煩地翻書。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "小滿蹲在紅泥爐前，往炭裡添了一塊。砂銚裡的水剛開始冒泡，細細的，一粒一粒浮上來。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "蟹眼。還早。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "師父沒有回頭。他坐在櫃台後面擦一只舊壺，擦了快一個時辰，壺早就亮得能照人了。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)他今晚擦什麼都擦很久。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "水聲變粗，泡泡大了一圈，翻上來就破。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "魚眼。溫壺。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "小滿提起砂銚，把滾水澆在壺身上。熱氣騰起來，糊了她一臉。壺是紫砂的，比她還老，壺蓋上有一道金補的細裂，像一條睡著的蛇。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "置茶，沖水，蓋上壺蓋，數到五。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一泡，倒掉。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "茶湯淌進茶盤底下的竹槽，琥珀色的，帶一點紅。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)每次都覺得可惜。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "可惜？", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "小滿嚇了一跳。她什麼都沒說出口。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "妳倒第一泡的時候，嘴角都往下撇。七年了。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "茶葉一路曬、炒、揉、焙，沾了灰，沾了手汗，沾了路上的風。第一泡把這些帶走。總得有人替後面的先苦過一遍。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "那它也太倒楣了。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "嗯。是倒楣。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "師父放下舊壺，看了門口一眼。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門框上有三道刻痕。最低的是小滿的，旁邊歪歪扭扭刻了個「滿」字。上面兩道高得多，刻得很深，一個是「硯」，一個是「遲」。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)問過一次是誰。那天他煮糊了一整壺茶。之後就不問了。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "敲門聲。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "三下，不輕不重，像是算好了力氣。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "小滿拉開門閂。風雨灌進來，燈火矮了半截，又撐了回來。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門外站著一個男人。斗笠壓得很低，蓑衣往下淌水，背上用油布裹著一個長條的東西。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)劍。裹得再厚，那個形狀都是劍。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "溫伯。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有看小滿，越過她的肩膀，看著櫃台後面的老人。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "進來。地上濕，脫鞋。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "男人頓了一下，好像這句話讓他想起了什麼。他彎腰脫鞋，把斗笠掛在門邊一根釘子上。那根釘子小滿從來不知道是做什麼用的。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)現在知道了。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "斗笠底下是一張三十歲上下的臉，眉骨很高，嘴唇抿得很緊，像一道收好的刀口。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "小滿，泡茶。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她回到爐邊重新溫壺。男人在靠窗那張桌子坐下，油布包橫放在膝上，沒有解開。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "他來了嗎？", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "還沒。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "他會來嗎？", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "會。這裡是他家。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "早就不是了。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "師父沒接話。小滿把第一泡倒進竹槽，男人的視線跟著那道茶湯走了一段，又收回去。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二泡，她用公道杯勻了，倒進他面前的小杯。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "天亮，一線關。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "我知道。他託人送來的信，我也看了。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "您不攔？", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "我攔過你們一次。攔不住的東西，我不攔第二次。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "男人端起茶杯，沒有喝，只是握著。熱氣從他指縫裡往上爬。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "十年前那一晚，我在關口跟白鷺門主的兒子比劍。他輸了。我收了劍，留了他一口氣。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "天亮，人死在原地。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "阿遲當夜就走了。帶走我的劍，留下他自己的，在門口刻了一句：人是我殺的。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他說這幾句的時候，聲音一點起伏都沒有，像在念一張別人寫的帖子。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "我不是來問為什麼的。十年夠久了，我只是來把事情做完。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他把茶喝了，杯底輕輕放回桌上，然後抬頭，第一次正眼看她。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "妳是？", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "小滿。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "節氣。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.WenBo, character: "溫伯", dialogue: "撿到她那天是小滿。", background: Background.Root_Act1_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "⋯⋯撿到我那天，他在磨墨。撿到阿遲那天，他去晚了一步。", background: Background.Root_Act1_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著門框上那兩道刻痕，看了很久，然後起身上了閣樓。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "油布包一直背在身上，沒有放下。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)他背的是另一個人的劍。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小滿", dialogue: "(內心)背了十年。", background: Background.Root_Act1_S0, portrait: Portrait.XiaoMan_Base },
];
